"use client";

import * as React from "react";
import {
  motion,
  useAnimationControls,
  useReducedMotion,
} from "motion/react";

export interface AmountInputProps {
  value?: number | null;
  defaultValue?: number;
  onChange?: (value: number | null, formattedValue: string) => void;
  currency?: string;
  format?: "international" | "indian";
  placeholder?: string;
  allowDecimals?: boolean;
  maxDecimals?: number;
  min?: number;
  max?: number;
  label?: string;
  helperText?: string;
  quickAddPresets?: number[];
  className?: string;
}

function getDecimalLimit(allowDecimals: boolean, maxDecimals: number) {
  if (!allowDecimals || !Number.isFinite(maxDecimals)) {
    return allowDecimals && maxDecimals === Number.POSITIVE_INFINITY ? 100 : 0;
  }
  return Math.min(100, Math.max(0, Math.floor(maxDecimals)));
}

function sanitizeAmount(rawValue: string, decimalLimit: number) {
  let integer = "";
  let fraction = "";
  let hasDecimal = false;

  for (const character of rawValue) {
    if (character >= "0" && character <= "9") {
      if (hasDecimal) {
        if (fraction.length < decimalLimit) fraction += character;
      } else {
        integer += character;
      }
    } else if (character === "." && decimalLimit > 0 && !hasDecimal) {
      hasDecimal = true;
    }
  }

  return { integer, fraction, hasDecimal };
}

function groupInteger(integer: string, format: "international" | "indian") {
  if (format === "indian" && integer.length > 3) {
    const lastThree = integer.slice(-3);
    const leading = integer.slice(0, -3).replace(/\B(?=(\d{2})+(?!\d))/g, ",");
    return `${leading},${lastThree}`;
  }

  return integer.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function formatAmount(
  rawValue: string,
  format: "international" | "indian",
  decimalLimit: number
) {
  const { integer, fraction, hasDecimal } = sanitizeAmount(
    rawValue.replace(/,/g, ""),
    decimalLimit
  );
  const groupedInteger = groupInteger(integer, format);

  if (hasDecimal && decimalLimit > 0) {
    return `${groupedInteger}.${fraction}`;
  }

  return groupedInteger;
}

function parseAmount(formattedValue: string): number | null {
  const normalized = formattedValue.replace(/,/g, "");
  if (!normalized || normalized === ".") return null;

  const amount = Number(normalized);
  return Number.isFinite(amount) ? amount : null;
}

function formatExternalValue(
  value: number | null | undefined,
  format: "international" | "indian",
  decimalLimit: number
) {
  return value == null
    ? ""
    : formatAmount(String(value), format, decimalLimit);
}

export function AmountInput({
  value,
  defaultValue,
  onChange,
  currency = "$",
  format = "international",
  placeholder = "0.00",
  allowDecimals = true,
  maxDecimals = 2,
  min,
  max,
  label,
  helperText,
  quickAddPresets = [],
  className,
}: AmountInputProps) {
  const decimalLimit = getDecimalLimit(allowDecimals, maxDecimals);
  const isControlled = value !== undefined;
  const initialValue = isControlled ? value : (defaultValue ?? null);
  const [displayValue, setDisplayValue] = React.useState(() =>
    formatExternalValue(initialValue, format, decimalLimit)
  );
  const [lastExternalValue, setLastExternalValue] = React.useState(value);
  const [lastEmittedAmount, setLastEmittedAmount] = React.useState<number | null>(
    null
  );
  const inputRef = React.useRef<HTMLInputElement>(null);
  const pendingCaretRef = React.useRef<number | null>(null);
  const skipCaretRestoreRef = React.useRef(false);
  const previousFormatRef = React.useRef({ format, allowDecimals, maxDecimals });
  const animationControls = useAnimationControls();
  const shouldReduceMotion = useReducedMotion();
  const inputId = React.useId();
  const helperId = React.useId();

  if (isControlled && !Object.is(lastExternalValue, value)) {
    setLastExternalValue(value);
    if (!Object.is(value, lastEmittedAmount)) {
      setDisplayValue(formatExternalValue(value, format, decimalLimit));
      setLastEmittedAmount(null);
    }
  }

  const renderedValue = displayValue;
  const amount = parseAmount(displayValue);
  const belowMinimum = amount !== null && min !== undefined && amount < min;
  const aboveMaximum = amount !== null && max !== undefined && amount > max;
  const outOfRange = belowMinimum || aboveMaximum;
  const validationMessage = belowMinimum
    ? `Amount must be at least ${min}.`
    : aboveMaximum
      ? `Amount must be no more than ${max}.`
      : null;

  const triggerRecoil = React.useCallback(() => {
    if (shouldReduceMotion) return;
    animationControls.stop();
    animationControls.set({ x: 0 });
    void animationControls.start({
      x: [-2, 2, -1, 1, 0],
      transition: { duration: 0.26, ease: "easeOut" },
    });
  }, [animationControls, shouldReduceMotion]);

  const commitRawValue = React.useCallback(
    (rawValue: string, digitsBeforeCursor?: number) => {
      const nextValue = formatAmount(rawValue, format, decimalLimit);
      if (digitsBeforeCursor !== undefined) {
        pendingCaretRef.current = digitsBeforeCursor;
      }
      setDisplayValue(nextValue);

      const nextAmount = parseAmount(nextValue);
      if (isControlled) setLastEmittedAmount(nextAmount);
      onChange?.(nextAmount, nextValue);
      if (
        (nextAmount !== null && min !== undefined && nextAmount < min) ||
        (nextAmount !== null && max !== undefined && nextAmount > max)
      ) {
        triggerRecoil();
      }
    },
    [decimalLimit, format, isControlled, max, min, onChange, triggerRecoil]
  );

  React.useLayoutEffect(() => {
    const previous = previousFormatRef.current;
    if (
      previous.format === format &&
      previous.allowDecimals === allowDecimals &&
      previous.maxDecimals === maxDecimals
    ) {
      return;
    }

    const input = inputRef.current;
    if (input && document.activeElement === input) {
      const cursor = input.selectionStart ?? 0;
      pendingCaretRef.current = displayValue
        .slice(0, cursor)
        .replace(/\D/g, "").length;
    }
    setDisplayValue(formatAmount(displayValue, format, decimalLimit));
    previousFormatRef.current = { format, allowDecimals, maxDecimals };
    skipCaretRestoreRef.current = true;
  }, [allowDecimals, decimalLimit, displayValue, format, maxDecimals]);

  React.useLayoutEffect(() => {
    if (skipCaretRestoreRef.current) {
      skipCaretRestoreRef.current = false;
      return;
    }

    const digitsBeforeCursor = pendingCaretRef.current;
    const input = inputRef.current;
    if (
      digitsBeforeCursor === null ||
      !input ||
      document.activeElement !== input
    ) {
      pendingCaretRef.current = null;
      return;
    }

    let digitCount = 0;
    let nextPosition = 0;
    if (digitsBeforeCursor > 0) {
      for (let index = 0; index < displayValue.length; index += 1) {
        nextPosition = index + 1;
        if (/\d/.test(displayValue[index])) digitCount += 1;
        if (digitCount >= digitsBeforeCursor) break;
      }
      if (digitCount < digitsBeforeCursor) nextPosition = displayValue.length;
    }

    input.setSelectionRange(nextPosition, nextPosition);
    pendingCaretRef.current = null;
  }, [displayValue]);

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = event.currentTarget.value;
    const cursor = event.currentTarget.selectionStart ?? 0;
    const digitsBeforeCursor = rawValue.slice(0, cursor).replace(/\D/g, "").length;
    commitRawValue(rawValue, digitsBeforeCursor);
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    const input = event.currentTarget;
    const cursor = input.selectionStart ?? 0;
    if (
      event.key !== "Backspace" ||
      input.selectionStart !== input.selectionEnd ||
      cursor === 0 ||
      displayValue[cursor - 1] !== ","
    ) {
      return;
    }

    event.preventDefault();
    const digitsBeforeComma = displayValue
      .slice(0, cursor - 1)
      .replace(/\D/g, "").length;
    const digitToRemove = digitsBeforeComma - 1;
    if (digitToRemove < 0) return;

    const rawValue = displayValue.replace(/,/g, "");
    let seenDigits = 0;
    let removeIndex = -1;
    for (let index = 0; index < rawValue.length; index += 1) {
      if (/\d/.test(rawValue[index])) {
        if (seenDigits === digitToRemove) {
          removeIndex = index;
          break;
        }
        seenDigits += 1;
      }
    }

    if (removeIndex !== -1) {
      commitRawValue(
        `${rawValue.slice(0, removeIndex)}${rawValue.slice(removeIndex + 1)}`,
        digitToRemove
      );
    }
  };

  const handleQuickAdd = (preset: number) => {
    if (!Number.isFinite(preset)) return;
    const nextAmount = (amount ?? 0) + preset;
    const precision = decimalLimit;
    const roundedAmount = Number(nextAmount.toFixed(precision));
    commitRawValue(String(roundedAmount));
  };

  return (
    <motion.div
      animate={animationControls}
      className={`w-full max-w-[420px] ${className ?? ""}`}
    >
      {label && (
        <label
          htmlFor={inputId}
          className="mb-2 block text-xs font-medium text-zinc-300"
        >
          {label}
        </label>
      )}

      <div
        className={[
          "group relative flex w-full items-center rounded-xl border bg-[#101216] px-3.5 py-2.5 transition-all duration-200",
          "border-white/[0.08] focus-within:border-white/20 focus-within:bg-[#14171d]",
          "focus-within:shadow-[inset_0_1px_0_rgba(255,255,255,0.06),0_2px_12px_rgba(0,0,0,0.6)]",
          outOfRange && "border-rose-500/40 focus-within:border-rose-400/60",
        ]
          .filter(Boolean)
          .join(" ")}
      >
        <span
          aria-hidden="true"
          className="mr-2 select-none font-mono text-sm font-medium text-zinc-500 transition-colors duration-200 group-focus-within:text-zinc-200"
        >
          {currency}
        </span>
        <input
          ref={inputRef}
          id={inputId}
          type="text"
          inputMode={decimalLimit > 0 ? "decimal" : "numeric"}
          autoComplete="off"
          spellCheck={false}
          value={renderedValue}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          aria-label={label ? undefined : "Amount"}
          aria-invalid={outOfRange}
          aria-describedby={
            validationMessage || helperText ? helperId : undefined
          }
          className="w-full min-w-0 bg-transparent font-mono text-sm tracking-tight text-[#f5f5f7] outline-none placeholder:text-zinc-600 tabular-nums"
        />
      </div>

      {(validationMessage || helperText) && (
        <p
          id={helperId}
          aria-live={validationMessage ? "polite" : undefined}
          className={`mt-2 text-xs leading-relaxed ${
            validationMessage ? "text-rose-300" : "text-zinc-500"
          }`}
        >
          {validationMessage ?? helperText}
        </p>
      )}

      {quickAddPresets.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-2" aria-label="Quick add amounts">
          {quickAddPresets.map((preset, index) => (
            <motion.button
              key={`${preset}-${index}`}
              type="button"
              whileTap={shouldReduceMotion ? undefined : { scale: 0.95 }}
              onClick={() => handleQuickAdd(preset)}
              className="rounded-md border border-white/[0.06] bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-zinc-400 transition-colors hover:bg-white/[0.08] hover:text-zinc-200 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-lime-400"
            >
              +{preset.toLocaleString("en-US")}
            </motion.button>
          ))}
        </div>
      )}
    </motion.div>
  );
}
